"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { requestOtp, verifyOtp } from "@/lib/api";
import { saveToken } from "@/lib/auth";
import GradientOrbs from "@/components/GradientOrbs";
import Magnetic from "@/components/Magnetic";

export default function LoginPage() {
  const [email, setEmail] = useState("");
  const [code, setCode] = useState("");
  const [step, setStep] = useState<"email" | "code">("email");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [shake, setShake] = useState(false);
  const [justSent, setJustSent] = useState(false);
  const router = useRouter();

  function triggerShake() {
    setShake(true);
    setTimeout(() => setShake(false), 500);
  }

  async function handleRequestOtp() {
    setLoading(true);
    setError("");
    try {
      await requestOtp(email);
      setJustSent(true);
      setTimeout(() => setStep("code"), 550);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong");
      triggerShake();
    } finally {
      setLoading(false);
    }
  }

  async function handleVerifyOtp() {
    setLoading(true);
    setError("");
    try {
      const data = await verifyOtp(email, code);
      saveToken(data.access_token);
      router.push("/home");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Invalid or expired code");
      triggerShake();
    } finally {
      setLoading(false);
    }
  }

  return (
    <main className="relative flex min-h-screen items-center justify-center overflow-hidden bg-graphite px-4">
      <GradientOrbs />

      <Link
        href="/"
        className="animate-fade-in-up absolute left-8 top-7 z-10 flex items-center gap-2"
      >
        <span className="flex h-8 w-8 items-center justify-center rounded-xl bg-gradient-to-br from-gold to-violet font-display text-sm font-bold text-graphite">
          Q
        </span>
        <span className="font-display text-lg font-bold text-ink">QueryMind</span>
      </Link>

      <div
        className={`animate-spring-in relative z-10 w-full max-w-sm rounded-3xl border border-white/10 bg-surface/70 p-8 shadow-[0_30px_80px_-20px_rgba(0,0,0,0.6)] backdrop-blur-2xl ${
          shake ? "animate-shake" : ""
        }`}
      >
        <div className="mb-7 flex flex-col items-center gap-2 text-center">
          <h1 className="font-display text-2xl font-bold text-ink">Welcome back</h1>
          <p className="text-sm text-mist">Sign in to keep querying your data.</p>
        </div>

        <div className="mb-7 flex items-center justify-center gap-2">
          <div
            className={`h-1.5 rounded-full transition-all duration-500 ${
              step === "email" ? "w-8 bg-gold" : "w-4 bg-gold/40"
            }`}
          />
          <div
            className={`h-1.5 rounded-full transition-all duration-500 ${
              step === "code" ? "w-8 bg-violet" : "w-4 bg-white/10"
            }`}
          />
        </div>

        {step === "email" && (
          <div className="animate-fade-in-up flex flex-col gap-4">
            <div className="relative">
              <input
                type="email"
                placeholder="you@example.com"
                className="w-full rounded-2xl border border-white/10 bg-black/20 px-5 py-3.5 text-ink placeholder:text-mist/60 transition-all duration-200 focus:border-gold/50 focus:outline-none focus:ring-4 focus:ring-gold/10"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && email && handleRequestOtp()}
              />
              {justSent && (
                <span className="absolute right-4 top-1/2 -translate-y-1/2">
                  <span className="animate-success-burst relative flex h-5 w-5 items-center justify-center rounded-full bg-gold text-graphite">
                    ✓
                    <span className="animate-ring-expand absolute inset-0 rounded-full border-2 border-gold" />
                  </span>
                </span>
              )}
            </div>
            <Magnetic strength={30}>
              <button
                onClick={handleRequestOtp}
                disabled={loading || !email}
                className="flex w-full cursor-pointer items-center justify-center gap-2 rounded-2xl bg-gradient-to-r from-gold to-violet px-4 py-3.5 font-display font-bold text-graphite shadow-[0_15px_40px_-12px_rgba(139,92,246,0.5)] transition-transform duration-150 hover:-translate-y-0.5 active:scale-95 disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:translate-y-0"
              >
                {loading ? (
                  <>
                    <span className="h-4 w-4 animate-spin rounded-full border-2 border-graphite/30 border-t-graphite" />
                    Sending...
                  </>
                ) : (
                  "Send Code"
                )}
              </button>
            </Magnetic>
          </div>
        )}

        {step === "code" && (
          <div className="animate-fade-in-up flex flex-col gap-4">
            <p className="text-center text-sm text-mist">
              Enter the code sent to <span className="text-ink">{email}</span>
            </p>
            <input
              type="text"
              placeholder="000000"
              maxLength={6}
              autoFocus
              className="w-full rounded-2xl border border-white/10 bg-black/20 px-5 py-3.5 text-center font-mono text-xl tracking-[0.5em] text-ink placeholder:text-mist/40 transition-all duration-200 focus:border-violet/50 focus:outline-none focus:ring-4 focus:ring-violet/10"
              value={code}
              onChange={(e) => setCode(e.target.value.replace(/\D/g, ""))}
              onKeyDown={(e) => e.key === "Enter" && code && handleVerifyOtp()}
            />
            <Magnetic strength={30}>
              <button
                onClick={handleVerifyOtp}
                disabled={loading || code.length < 6}
                className="flex w-full cursor-pointer items-center justify-center gap-2 rounded-2xl bg-gradient-to-r from-violet to-gold px-4 py-3.5 font-display font-bold text-graphite shadow-[0_15px_40px_-12px_rgba(242,184,75,0.4)] transition-transform duration-150 hover:-translate-y-0.5 active:scale-95 disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:translate-y-0"
              >
                {loading ? (
                  <>
                    <span className="h-4 w-4 animate-spin rounded-full border-2 border-graphite/30 border-t-graphite" />
                    Verifying...
                  </>
                ) : (
                  "Verify & Continue"
                )}
              </button>
            </Magnetic>
            <button
              onClick={() => {
                setStep("email");
                setCode("");
                setJustSent(false);
                setError("");
              }}
              className="cursor-pointer text-center font-mono text-xs text-mist underline-offset-4 hover:text-ink hover:underline"
            >
              Use a different email
            </button>
          </div>
        )}

        {error && (
          <p className="mt-4 rounded-xl border border-red-500/20 bg-red-500/10 px-3 py-2 text-center text-sm text-red-300">
            {error}
          </p>
        )}
      </div>
    </main>
  );
}
